package androidx.window.extensions;import java.util.*;import java.util.function.Consumer;import android.app.Activity;import android.graphics.Rect;public class WindowExtensionsProvider{public static final Extensions extensions=new Extensions();public static Extensions getWindowExtensions(){return extensions;}public static class Extensions{public final Component component=new Component();public Component getWindowLayoutComponent(){return component;}}public static class Component{public Consumer<Info> consumer,removed;public void addWindowLayoutInfoListener(Activity a,Consumer<Info> c){consumer=c;}public void removeWindowLayoutInfoListener(Consumer<Info> c){removed=c;if(consumer==c)consumer=null;}}public static class Info{public List<Feature> getDisplayFeatures(){return Arrays.asList(new Feature(new Rect(0,400,900,420)),new Feature(new Rect(400,0,400,900)));}}public static class Feature{final Rect rect;public Feature(Rect r){rect=r;}public Rect getBounds(){return rect;}}}